import{_ as a,o as e,c as n,ag as i}from"./chunks/framework.CAXxHpAX.js";const k=JSON.parse('{"title":"项目结构","description":"","frontmatter":{},"headers":[],"relativePath":"guide/project-structure.md","filePath":"guide/project-structure.md","lastUpdated":null}'),t={name:"guide/project-structure.md"};function p(l,s,o,d,c,h){return e(),n("div",null,[...s[0]||(s[0]=[i(`<h1 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h1><p>Aether 项目采用 UI 与逻辑分离的架构，<code>.ae</code> 文件负责声明式 UI，<code>.rs</code> 文件负责业务逻辑，通过文件名自动配对绑定。</p><h2 id="完整目录结构" tabindex="-1">完整目录结构 <a class="header-anchor" href="#完整目录结构" aria-label="Permalink to &quot;完整目录结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>myapp/</span></span>
<span class="line"><span>  aether.toml                 # 项目配置文件</span></span>
<span class="line"><span>  src/</span></span>
<span class="line"><span>    ui/</span></span>
<span class="line"><span>      home.ae                 # 首页 UI（每个 .ae 文件对应一个页面）</span></span>
<span class="line"><span>      detail.ae               # 详情页 UI</span></span>
<span class="line"><span>      routes.ae               # 导航配置（特殊文件）</span></span>
<span class="line"><span>      drawers.ae              # 抽屉定义（特殊文件）</span></span>
<span class="line"><span>      components/             # 可复用组件目录</span></span>
<span class="line"><span>        card.ae               # Card 组件</span></span>
<span class="line"><span>    logic/</span></span>
<span class="line"><span>      home.rs                 # 首页逻辑（与 home.ae 配对）</span></span>
<span class="line"><span>      detail.rs               # 详情页逻辑（与 detail.ae 配对）</span></span>
<span class="line"><span>    themes/</span></span>
<span class="line"><span>      light.toml              # 浅色主题</span></span>
<span class="line"><span>      dark.toml               # 深色主题</span></span>
<span class="line"><span>    i18n/</span></span>
<span class="line"><span>      zh-CN.toml              # 中文翻译</span></span>
<span class="line"><span>      en.toml                 # 英文翻译</span></span>
<span class="line"><span>    assets/</span></span>
<span class="line"><span>      *.svg                   # SVG 图标资源（支持子目录）</span></span></code></pre></div><h2 id="核心约定" tabindex="-1">核心约定 <a class="header-anchor" href="#核心约定" aria-label="Permalink to &quot;核心约定&quot;">​</a></h2><h3 id="ae-与-rs-一一配对" tabindex="-1">.ae 与 .rs 一一配对 <a class="header-anchor" href="#ae-与-rs-一一配对" aria-label="Permalink to &quot;.ae 与 .rs 一一配对&quot;">​</a></h3><p><code>src/ui/</code> 下的 <code>.ae</code> 文件和 <code>src/logic/</code> 下的 <code>.rs</code> 文件通过<strong>文件名</strong>自动配对：</p><table tabindex="0"><thead><tr><th>UI 文件</th><th>逻辑文件</th><th>说明</th></tr></thead><tbody><tr><td><code>src/ui/home.ae</code></td><td><code>src/logic/home.rs</code></td><td>文件名相同，自动绑定</td></tr><tr><td><code>src/ui/detail.ae</code></td><td><code>src/logic/detail.rs</code></td><td>文件名相同，自动绑定</td></tr></tbody></table><p>在 <code>.ae</code> 文件中通过 Rust 结构体名称引用逻辑方法：</p><div class="language-ae vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ae</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VStack {</span></span>
<span class="line"><span>    Text(&quot;Hello!&quot;)</span></span>
<span class="line"><span>    Button(&quot;Click me&quot; onClick={Home.on_click()})</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>其中 <code>Home</code> 是 <code>home.rs</code> 中定义的 Rust 结构体名称。</p><h3 id="rust-结构体名称用于绑定解析" tabindex="-1">Rust 结构体名称用于绑定解析 <a class="header-anchor" href="#rust-结构体名称用于绑定解析" aria-label="Permalink to &quot;Rust 结构体名称用于绑定解析&quot;">​</a></h3><p><code>.rs</code> 文件中的 <strong>Rust 结构体名称</strong>（不是文件名）是绑定的关键标识。例如在 <code>home.rs</code> 中：</p><div class="language-rust vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">pub</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Home</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    count</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> i32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">impl</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Home</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    pub</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> fn</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Self</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        Self</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { count</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    pub</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> fn</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> on_click</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;mut</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> self</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        self</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">count </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>.ae</code> 文件中通过 <code>Home.on_click()</code> 来引用这个方法。构建时 Aether 会验证所有绑定引用是否存在于对应的 <code>.rs</code> 模块中。</p><h3 id="routes-ae-导航配置" tabindex="-1">routes.ae -- 导航配置 <a class="header-anchor" href="#routes-ae-导航配置" aria-label="Permalink to &quot;routes.ae -- 导航配置&quot;">​</a></h3><p><code>routes.ae</code> 是一个<strong>特殊文件</strong>，用于定义应用的导航结构，不会被生成为独立的页面视图。它定义了 Tab 导航、页面路由等全局导航配置：</p><div class="language-ae vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ae</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Routes {</span></span>
<span class="line"><span>    Tabs {</span></span>
<span class="line"><span>        Tab(icon=&quot;house&quot; label=&quot;首页&quot;) { Home }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="drawers-ae-抽屉定义" tabindex="-1">drawers.ae -- 抽屉定义 <a class="header-anchor" href="#drawers-ae-抽屉定义" aria-label="Permalink to &quot;drawers.ae -- 抽屉定义&quot;">​</a></h3><p><code>drawers.ae</code> 也是一个<strong>特殊文件</strong>，用于定义侧边抽屉、底部弹出面板等容器。与 <code>routes.ae</code> 类似，它不会被生成为独立页面，而是作为全局 UI 组件注册。</p><h3 id="components-目录-可复用组件" tabindex="-1">components/ 目录 -- 可复用组件 <a class="header-anchor" href="#components-目录-可复用组件" aria-label="Permalink to &quot;components/ 目录 -- 可复用组件&quot;">​</a></h3><p><code>src/ui/components/</code> 目录下的每个 <code>.ae</code> 文件定义一个可复用组件。文件名会自动转换为 <strong>PascalCase</strong> 组件名：</p><table tabindex="0"><thead><tr><th>文件路径</th><th>组件名</th></tr></thead><tbody><tr><td><code>components/card.ae</code></td><td><code>Card</code></td></tr><tr><td><code>components/nav_bar.ae</code></td><td><code>NavBar</code></td></tr><tr><td><code>components/user_avatar.ae</code></td><td><code>UserAvatar</code></td></tr></tbody></table><p>组件可以在任意页面 <code>.ae</code> 文件中直接使用：</p><div class="language-ae vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ae</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VStack {</span></span>
<span class="line"><span>    Card(title=&quot;Hello&quot;)</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="其他目录" tabindex="-1">其他目录 <a class="header-anchor" href="#其他目录" aria-label="Permalink to &quot;其他目录&quot;">​</a></h2><h3 id="themes-主题配置" tabindex="-1">themes/ -- 主题配置 <a class="header-anchor" href="#themes-主题配置" aria-label="Permalink to &quot;themes/ -- 主题配置&quot;">​</a></h3><p>每个 <code>.toml</code> 文件定义一个主题，文件名即为主题名（如 <code>light.toml</code> 定义 <code>light</code> 主题）。主题包含颜色、字体、间距、圆角和样式等配置。</p><h3 id="i18n-国际化" tabindex="-1">i18n/ -- 国际化 <a class="header-anchor" href="#i18n-国际化" aria-label="Permalink to &quot;i18n/ -- 国际化&quot;">​</a></h3><p>每个 <code>.toml</code> 文件对应一种语言，文件名即为 locale 标识（如 <code>zh-CN.toml</code>）。在 <code>.ae</code> 文件中通过 <code>$i18n.key</code> 引用翻译文本。</p><h3 id="assets-静态资源" tabindex="-1">assets/ -- 静态资源 <a class="header-anchor" href="#assets-静态资源" aria-label="Permalink to &quot;assets/ -- 静态资源&quot;">​</a></h3><p>目前支持 <code>.svg</code> 格式的图标资源，支持子目录组织。在 <code>.ae</code> 文件中通过 <code>$assets.icon_name</code> 引用。子目录使用 <code>.</code> 分隔，例如 <code>assets/tab/home.svg</code> 对应 <code>$assets.tab.home</code>。</p>`,32)])])}const u=a(t,[["render",p]]);export{k as __pageData,u as default};
